"""Asterisk configuration snippets rendered from the environment.

Rendering only writes local files (default ``build/asterisk``, git-ignored).
It never connects to, or modifies, a PBX.
"""

from __future__ import annotations

import os
from pathlib import Path

from voice_agent.config import Settings

DIALPLAN = """\
; ---------------------------------------------------------------------------
; voice-monday-agent TEST route  (generated by `voice-agent render-asterisk`)
; Affects ONLY extension @@EXT@@. Remove this file + its include to revert.
; ---------------------------------------------------------------------------
[voice-monday-test]
exten => @@EXT@@,1,NoOp(voice-monday-agent test call from ${CALLERID(num)})
 same => n,Stasis(@@APP@@)
 same => n,Hangup()
"""

ARI_USER = """\
; ---------------------------------------------------------------------------
; voice-monday-agent ARI user (generated). Append to /etc/asterisk/ari.conf
; (FreePBX: /etc/asterisk/ari_additional_custom.conf). Keep this file private.
; The [general] section of ari.conf must contain `enabled = yes`.
; ---------------------------------------------------------------------------
[@@USER@@]
type = user
read_only = no
password = @@PASSWORD@@
password_format = plain
"""

HTTP_CONF = """\
; ---------------------------------------------------------------------------
; Asterisk built-in HTTP server, required by ARI. Merge into the EXISTING
; [general] section of /etc/asterisk/http.conf (do not create a second one).
; FreePBX: Settings > Advanced Settings > "Asterisk Builtin mini-HTTP server".
; ---------------------------------------------------------------------------
[general]
enabled = yes
; 127.0.0.1 if the agent runs on the PBX host; otherwise the PBX LAN IP.
; Never expose 8088 to the internet.
bindaddr = @@BIND@@
bindport = @@PORT@@
"""


def _replace(template: str, values: dict[str, str]) -> str:
    for key, value in values.items():
        template = template.replace(f"@@{key}@@", value)
    return template


def render_all(settings: Settings, out_dir: Path) -> list[Path]:
    out_dir.mkdir(parents=True, exist_ok=True)
    from urllib.parse import urlsplit

    url = urlsplit(settings.asterisk_ari_url or "http://127.0.0.1:8088")
    host = url.hostname or "127.0.0.1"
    values = {
        "EXT": settings.asterisk_test_extension,
        "APP": settings.asterisk_stasis_app,
        "USER": settings.asterisk_ari_username or "voice-monday",
        "PASSWORD": settings.asterisk_ari_password or "CHANGE_ME_TO_A_LONG_RANDOM_PASSWORD",
        "BIND": "127.0.0.1" if host in ("127.0.0.1", "localhost") else host,
        "PORT": str(url.port or 8088),
    }
    files = {
        "extensions_voice_monday.conf": DIALPLAN,
        "ari_voice_monday.conf": ARI_USER,
        "http_voice_monday.conf": HTTP_CONF,
    }
    written = []
    for name, template in files.items():
        path = out_dir / name
        path.write_text(_replace(template, values), encoding="utf-8")
        if name.startswith("ari_"):
            os.chmod(path, 0o600)  # contains the ARI password
        written.append(path)
    return written
